//! Axes, hoes, shovels (`block_transformer` data) and honeycomb on blocks against the real vanilla classes: every case of
//! `tests/oracle/scenarios/item_blocks.txt` (generated by `gen_item_blocks.py`) was run through the vanilla oracle
//! (`scripts/entity-oracle.sh`: a real `ServerPlayer` sending `ServerboundUseItemOnPacket`) and the fixture holds the blocks, the
//! inventory and the item entities afterwards. This replays the same cases through our item code.
//! Regenerate: `python3 gen_item_blocks.py > item_blocks.txt; scripts/entity-oracle.sh .../item_blocks.txt -o .../fixtures/entity_oracle/item_blocks.txt`.

use crate::common;

use mc_core::direction::Direction;
use mc_core::ident::Identifier;
use mc_core::phys::{BlockHitResult, Vec3};
use mc_core::pos::BlockPos;
use mc_data::Item;
use mc_data::block::{Block, BlockState};
use mc_game::server::level::ServerLevel;
use mc_game::world::entity::{Entity, ServerPlayer};
use mc_game::world::item::block_transformer::BlockTransformer;
use mc_game::world::item::{InteractionHand, ItemStack, UseOnContext, item_stack_use_on};
use mc_game::world::level::levelgen::registries::load_vanilla_data;
use mc_game::world::level::{BlockGetter, LevelAccessor};
use mc_protocol::codec::GameProfile;
use std::collections::HashMap;
use std::sync::Arc;

fn parse_state(text: &str) -> BlockState {
    let (name, props) = match text.split_once('[') {
        Some((n, p)) => (n, Some(p.trim_end_matches(']'))),
        None => (text, None),
    };
    let mut state = Block::by_name(name)
        .unwrap_or_else(|| panic!("block {name}"))
        .default_state();
    for kv in props.into_iter().flat_map(|p| p.split(',')) {
        let (k, v) = kv.split_once('=').unwrap();
        state = state
            .with_property_str(k, v)
            .unwrap_or_else(|| panic!("property {kv} of {text}"));
    }
    state
}

fn serialize(state: BlockState) -> String {
    let mut s = state.block().name().to_string();
    let props: Vec<String> = state
        .values()
        .map(|(d, i)| format!("{}={}", d.name, d.values[i]))
        .collect();
    if !props.is_empty() {
        s.push('[');
        s.push_str(&props.join(","));
        s.push(']');
    }
    s
}

fn direction(name: &str) -> Direction {
    Direction::by_name(name).unwrap_or_else(|| panic!("direction {name}"))
}

struct Case {
    tool: String,
    block: String,
    above: Option<String>,
    face: Direction,
    /// Fixture lines after the header: `B ...`, `I ...`, `E ...`.
    expected: Vec<String>,
}

fn cases() -> Vec<Case> {
    let text =
        std::fs::read_to_string(common::entity_oracle::fixture_dir().join("item_blocks.txt"))
            .unwrap();
    let mut cases: Vec<Case> = Vec::new();
    for line in text.lines() {
        if let Some(rest) = line.strip_prefix("# CASE ") {
            let mut parts = rest.split(' ').skip(1);
            let mut get = |key: &str| parts.next().unwrap().strip_prefix(key).unwrap().to_owned();
            let tool = get("tool=");
            let block = get("block=");
            let above = get("above=");
            let face = get("face=");
            cases.push(Case {
                tool,
                block,
                above: (above != "none").then_some(above),
                face: direction(&face),
                expected: Vec::new(),
            });
        } else if let Some(case) = cases.last_mut()
            && (line.starts_with("B ") || line.starts_with("I ") || line.starts_with("E "))
        {
            case.expected.push(line.to_owned());
        }
    }
    cases
}

fn transformers() -> (
    HashMap<Identifier, Arc<BlockTransformer>>,
    Arc<mc_worldgen::biome::BiomeRegistry>,
) {
    let (_, biomes, registries) = load_vanilla_data();
    let registries = registries.expect("vanilla feature layer decodes");
    let map = registries
        .block_transformers
        .iter()
        .map(|(id, h)| (id.clone(), h.value().clone()))
        .collect();
    (map, biomes)
}

fn stack_text(stack: &ItemStack) -> String {
    common::entity_scenario::item_full(stack)
}

#[test]
fn block_transformers_and_honeycomb_match_vanilla() {
    let (transformers, _biomes) = transformers();
    let overworld = Identifier::parse("minecraft:overworld").unwrap();
    let mut failures = Vec::new();
    for (index, case) in cases().into_iter().enumerate() {
        // doors, trapdoors and copper chests consume the use themselves (`Block.useItemOn`/`useWithoutItem` run before the
        // item's `useOn` in `ServerPlayerGameMode.useItemOn`): the vanilla fixture shows the block's own interaction, which
        // belongs to the block behaviours, not to the item behaviours replayed here.
        if ["_door", "trapdoor", "copper_chest"]
            .iter()
            .any(|k| case.block.contains(k))
        {
            continue;
        }
        let mut level = ServerLevel::detached(overworld.clone());
        let mut steve = ServerPlayer::new(
            1,
            overworld.clone(),
            GameProfile {
                id: uuid::Uuid::from_u128(1),
                name: "Steve".into(),
                properties: vec![],
            },
            Default::default(),
        );
        steve.set_pos(0.5, -60.0, 0.5);
        steve.base_mut().set_on_ground_raw(true);
        steve.player.abilities.may_build = true;
        // the flat world's grass floor
        for x in 0..=4 {
            for z in -2..=2 {
                level.set_block(
                    BlockPos::new(x, -61, z),
                    Block::GRASS_BLOCK.default_state(),
                    3,
                    512,
                );
            }
        }
        let pos = BlockPos::new(2, -60, 0);
        level.set_block(pos, parse_state(&case.block), 3, 512);
        level.set_block(
            pos.above(),
            case.above
                .as_deref()
                .map_or_else(|| Block::AIR.default_state(), parse_state),
            3,
            512,
        );
        let item = Item::by_name(&format!("minecraft:{}", case.tool)).unwrap();
        steve.set_item_in_hand(InteractionHand::MainHand, ItemStack::new(item));
        let location = Vec3::new(
            f64::from(pos.x()) + 0.5 + f64::from(case.face.get_step_x()) * 0.5,
            f64::from(pos.y()) + 0.5 + f64::from(case.face.get_step_y()) * 0.5,
            f64::from(pos.z()) + 0.5 + f64::from(case.face.get_step_z()) * 0.5,
        );
        let hit = BlockHitResult {
            location,
            direction: case.face,
            block_pos: pos,
            miss: false,
            inside: false,
            world_border_hit: false,
        };
        let stack = steve.get_item_in_hand(InteractionHand::MainHand);
        let mut ctx = UseOnContext::new(
            Some(steve.context_player()),
            InteractionHand::MainHand,
            stack,
            hit,
        );
        if let Some(name) = ctx
            .item_stack
            .get(&mc_protocol::components::BLOCK_TRANSFORMER)
            .and_then(|h| h.name().cloned())
        {
            mc_game::world::item::block_transformer::transform_block(
                &transformers[&name],
                &mut ctx,
                &mut level,
                &mut steve,
            );
        } else {
            item_stack_use_on(&mut ctx, &mut level, &mut steve);
        }
        steve.set_item_in_hand(InteractionHand::MainHand, ctx.item_stack);
        let mut actual = Vec::new();
        for p in [pos, pos.above()] {
            let state = level.get_block_state(p);
            if !state.is_air() {
                actual.push(format!(
                    "B {} {} {} {}",
                    p.x(),
                    p.y(),
                    p.z(),
                    serialize(state)
                ));
            }
        }
        let held = steve.get_item_in_hand(InteractionHand::MainHand);
        if !held.is_empty() {
            actual.push(format!("I Steve 0 {}", stack_text(&held)));
        }
        let expected: Vec<String> = case
            .expected
            .iter()
            .filter(|l| !l.starts_with("E "))
            .cloned()
            .collect();
        if actual != expected {
            failures.push(format!("case {index} {} on {} above={:?} face={:?}\n  expected {expected:?}\n  actual   {actual:?}", case.tool, case.block, case.above, case.face));
        }
    }
    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
